      { key: 'competitions', label: 'كروت المسابقات' },
      { key: 'activities', label: 'الفعاليات' },
      // the cards of «خدماتنا» (a service page's own card follows it: AdminPages)
      { key: 'services', label: 'كروت خدماتنا' },
      { key: 'notifications', label: 'الإشعارات' }
