    { key: 'media', label: 'الصور', icon: 'photos' },
    // «سجل النشاط» (AdminActivity.html)
    { key: 'activity', label: 'النشاط', icon: 'clock', title: 'سجل النشاط' },
    { key: 'settings', label: 'الإعدادات', icon: 'gear' }
