    youtube: 'يوتيوب', whatsapp: 'واتساب', telegram: 'تيليجرام', spotify: 'سبوتيفاي',
    form: 'استمارة', calendar: 'تقويم', ticket: 'تذكرة / حجز', bus: 'رحلة', book: 'كتاب مقدس',
    music: 'ترانيم', photos: 'صور', video: 'فيديو', church: 'كنيسة', cross: 'صليب', heart: 'قلب',
    star: 'نجمة', megaphone: 'إعلان', gift: 'هدية', users: 'ناس / أسرة', map: 'مكان', info: 'معلومة', link: 'لينك',
    trophy: 'كأس / مسابقة', theatre: 'مسرح',
    messenger: 'ماسنجر', discord: 'ديسكورد', x: 'إكس (تويتر)', threads: 'ثريدز', snapchat: 'سناب شات',
    mail: 'إيميل', phone: 'تليفون'
