                if (!ok) return;
                A.withBusy(button, A.call('apiPageMediaDelete', m.id)).then(function (next) { r = next; media = next.media.slice(); draw(); A.toast('اتمسح'); })
                  .catch(function (error) { A.fail(error, box); });
